const state={rows:[],cols:[],profile:null,demo:true};

const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const norm=s=>String(s).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();

function parseNum(v){if(v===null||v===undefined||v==='')return null;let n=Number(String(v).replace(/,/g,''));return Number.isFinite(n)?n:null}
function uniq(a){return [...new Set(a)]}
function isBinary(vals){let u=uniq(vals.map(v=>norm(v)));return u.length===2}
function pct(x){return (x*100).toFixed(1)+'%'}
function fmt(n){if(!Number.isFinite(n))return '—';if(Math.abs(n)>=1e6)return (n/1e6).toFixed(1)+'M';if(Math.abs(n)>=1e3)return (n/1e3).toFixed(1)+'K';return Number.isInteger(n)?n.toLocaleString():n.toFixed(1)}
function mean(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0}
function median(a){if(!a.length)return 0;let b=[...a].sort((x,y)=>x-y);return b[Math.floor((b.length-1)/2)]}
function mode(a){let m=new Map();a.forEach(x=>m.set(String(x), (m.get(String(x))||0)+1));return [...m.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0]}

function looksId(c, vals){
  let n=norm(c), u=uniq(vals).length, ratio=u/Math.max(vals.length,1);
  return /( ^| )(id|order id|user id|customer id|product id|uuid|code)( |$)/.test(' '+n+' ') ||
         /(^| )(id|uuid|code)$/.test(n) || (ratio>.95 && /(id|number|no|key)/.test(n));
}
function profileData(rows,cols){
  const info={};
  cols.forEach(c=>{
    let vals=rows.map(r=>r[c]).filter(v=>v!==''&&v!==null&&v!==undefined);
    let nums=vals.map(parseNum).filter(v=>v!==null);
    let numRatio=vals.length?nums.length/vals.length:0;
    let u=uniq(vals).length;
    let id=looksId(c,vals);
    let binary=isBinary(vals);
    let type=numRatio>.9?'numeric':binary?'binary':u<=Math.min(30,Math.max(8,rows.length*.02))?'categorical':'text';
    info[c]={type,unique:u,missing:rows.length-vals.length,id,values:vals,nums};
  });
  let numeric=cols.filter(c=>info[c].type==='numeric'&&!info[c].id);
  let cats=cols.filter(c=>['categorical','binary'].includes(info[c].type)&&!info[c].id);
  let binaryCols=cols.filter(c=>info[c].type==='binary'&&!info[c].id);
  let measures=numeric.filter(c=>/(sales|revenue|amount|value|price|profit|cost|fee|income|score|rating|time|quantity|age|count)/.test(norm(c)))
    .concat(numeric.filter(c=>!/(sales|revenue|amount|value|price|profit|cost|fee|income|score|rating|time|quantity|age|count)/.test(norm(c))));
  return {info,numeric,cats,binaryCols,measures:[...new Set(measures)]};
}
function semantic(c){
  let n=norm(c);
  if(/repeat|retention|churn|converted|conversion|returned|returning/.test(n))return 'outcome';
  if(/discount|promotion|promo|coupon|weather|rain|weekday|day type/.test(n))return 'factor';
  if(/sales|revenue|amount|order value|value|profit|income|price|fee|cost/.test(n))return 'money';
  if(/rating|score|satisfaction/.test(n))return 'quality';
  if(/time|duration|delivery/.test(n))return 'time';
  if(/city|region|state|country|location/.test(n))return 'location';
  if(/cuisine|category|subcategory|segment|type|meal|restaurant|product/.test(n))return 'dimension';
  return 'dimension';
}
function bestMeasure(p){
  const scored=p.measures.map(c=>{
    let s=0,n=norm(c);
    if(/sales|revenue|amount|value|profit|income/.test(n))s+=10;
    if(/rating|score/.test(n))s+=4;
    if(/fee|cost/.test(n))s+=3;
    if(p.info[c].unique<10)s-=3;
    return [c,s];
  }).sort((a,b)=>b[1]-a[1]);
  return scored[0]?.[0]||p.numeric[0];
}
function findCol(q,p,types){
  let nq=norm(q), best=null, bs=0;
  p.cols?.forEach(()=>{});
  p.info && Object.keys(p.info).forEach(c=>{
    if(types&&!types.includes(p.info[c].type))return;
    let cn=norm(c), s=0;
    if(nq.includes(cn))s+=100;
    cn.split(' ').forEach(w=>{if(w.length>2&&nq.includes(w))s+=12});
    if(nq.includes(cn.replace(/ /g,'')))s+=20;
    if(s>bs){bs=s;best=c}
  });
  return best;
}
function makeSuggestions(p){
  const m=bestMeasure(p), cats=p.cats, out=p.binaryCols.find(c=>semantic(c)==='outcome')||p.binaryCols[0];
  let q=[];
  if(m&&cats[0])q.push(`Which ${cats[0]} have the highest average ${m}?`);
  if(m&&cats[1])q.push(`How does ${m} vary across ${cats[1]}?`);
  if(out&&cats.find(c=>c!==out))q.push(`What factors are associated with ${out}?`);
  if(out&&p.binaryCols.find(c=>c!==out))q.push(`Does ${p.binaryCols.find(c=>c!==out)} affect ${out}?`);
  if(m&&p.binaryCols.length)q.push(`Does ${p.binaryCols[0]} affect ${m}?`);
  if(p.cats.length>1&&m)q.push(`Which ${p.cats[0]} and ${p.cats[1]} combinations perform best?`);
  return uniq(q).slice(0,6);
}
function renderProfile(){
  let p=state.profile, info=p.info;
  $('profile').innerHTML=`<div class="profile-grid">
    <div class="profile-item"><strong>${state.rows.length.toLocaleString()}</strong><span>ROWS</span></div>
    <div class="profile-item"><strong>${state.cols.length}</strong><span>COLUMNS</span></div>
    <div class="profile-item"><strong>${p.numeric.length}</strong><span>NUMERIC</span></div>
    <div class="profile-item"><strong>${p.cats.length}</strong><span>CATEGORIES</span></div>
  </div>
  <div class="roles"><b>Detected roles</b><br>
  Measures: ${p.measures.slice(0,5).map(c=>`<span class="role-pill">${esc(c)}</span>`).join('')}
  <br>Dimensions: ${p.cats.slice(0,7).map(c=>`<span class="role-pill">${esc(c)}</span>`).join('')}
  ${p.binaryCols.length?`<br>Binary factors/outcomes: ${p.binaryCols.map(c=>`<span class="role-pill">${esc(c)}</span>`).join('')}`:''}
  </div>`;
}
function renderSuggestions(){
  $('suggestions').innerHTML=makeSuggestions(state.profile).map(q=>`<button class="suggestion">${esc(q)}</button>`).join('');
  document.querySelectorAll('.suggestion').forEach(b=>b.onclick=()=>{$('question').value=b.textContent});
}
function groupStats(rows,dim,measure,filter){
  let map=new Map();
  rows.forEach(r=>{
    if(filter&&!filter(r))return;
    let g=String(r[dim]??'Missing'), v=parseNum(r[measure]); if(v===null)return;
    if(!map.has(g))map.set(g,[]);map.get(g).push(v);
  });
  return [...map.entries()].map(([g,a])=>({g,n:a.length,avg:mean(a),sum:a.reduce((x,y)=>x+y,0)})).sort((a,b)=>b.avg-a.avg);
}
function repeatRate(rows,dim){
  let target=state.profile.binaryCols.find(c=>semantic(c)==='outcome')||state.profile.binaryCols.find(c=>/repeat|returned|churn|converted/i.test(c));
  if(!target)return [];
  let map=new Map();
  rows.forEach(r=>{let g=String(r[dim]??'Missing'),v=norm(r[target]);if(!map.has(g))map.set(g,[0,0]);map.get(g)[1]++;if(/yes|true|1|repeat|returned|converted/.test(v))map.get(g)[0]++});
  return [...map.entries()].map(([g,[yes,n]])=>({g,n,rate:yes/n})).sort((a,b)=>b.rate-a.rate);
}

function isSkillQuestion(q){
  return /\b(skill|skills|technical skill|technical skills|skill demand|skill frequency|required skills)\b/.test(norm(q));
}
function findSkillColumn(p){
  return Object.keys(p.info).find(c=>/required skills?|technical skills?|skills required/.test(norm(c))) || null;
}
function splitSkills(value){
  if(value===null||value===undefined||String(value).trim()==='') return [];
  return uniq(String(value)
    .split(/[|;,\n]+/)
    .map(s=>s.trim())
    .filter(Boolean)
    .map(s=>s.replace(/\s+/g,' ')));
}
function skillFrequency(rows, skillCol, categoryCol){
  const overall = new Map(), byCategory = new Map();
  rows.forEach(row=>{
    const category = categoryCol ? String(row[categoryCol]||'Unspecified') : 'All categories';
    splitSkills(row[skillCol]).forEach(skill=>{
      const key = skill.toLowerCase();
      if(!overall.has(key)) overall.set(key,{g:skill,count:0});
      overall.get(key).count++;
      if(!byCategory.has(category)) byCategory.set(category,new Map());
      const bucket=byCategory.get(category);
      if(!bucket.has(key)) bucket.set(key,{skill,count:0});
      bucket.get(key).count++;
    });
  });
  const overallRows=[...overall.values()].sort((a,b)=>b.count-a.count || a.g.localeCompare(b.g));
  const categoryRows=[];
  byCategory.forEach((skills,category)=>{
    [...skills.values()].sort((a,b)=>b.count-a.count).slice(0,5).forEach(item=>{
      categoryRows.push([category,item.skill,fmt(item.count)]);
    });
  });
  return {overallRows,categoryRows,categoryCount:byCategory.size};
}

function chartBar(title,data,valueKey,label,wide=false){
  let d=data.slice(0,10), max=Math.max(...d.map(x=>x[valueKey]),1);
  return `<div class="chart ${wide?'wide':''}"><h3>${esc(title)}</h3><p>Top ${d.length} groups</p>${d.map(x=>`<div class="bar-row"><div class="bar-label" title="${esc(x.g)}">${esc(x.g)}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,x[valueKey]/max*100)}%"></div></div><div class="bar-val">${valueKey==='rate'?pct(x[valueKey]):fmt(x[valueKey])}</div></div>`).join('')}</div>`;
}
function tableChart(title,headers,rows){
 return `<div class="chart wide"><h3>${esc(title)}</h3><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function mentionsColumn(question, column){
 const qn=norm(question), cn=norm(column);
 if(qn.includes(cn)) return true;
 const aliases={
  'job title':['job titles','role','roles','position','positions'],
  'job category':['job categories','category','categories','job family','job families'],
  'annual salary usd':['salary','salaries','annual pay','compensation'],
  'demand score':['demand','job demand','demand level'],
  'experience level':['experience','seniority','seniority level'],
  'remote work':['remote','work arrangement','work mode']
 };
 if(aliases[cn]?.some(a=>qn.includes(a))) return true;
 const words=cn.split(' ').filter(w=>w.length>2);
 return words.length>0 && words.every(w=>qn.includes(w) || qn.includes(w+'s'));
}

function detectPlan(q,p){
 let nq=norm(q), target=findCol(q,p), measure=target&&p.info[target]?.type==='numeric'?target:null;
 let dims=p.cats.filter(c=>mentionsColumn(q,c)).sort((a,b)=>norm(b).length-norm(a).length);
 let binary=p.binaryCols.filter(c=>nq.includes(norm(c)));
 if(!measure)measure=findCol(q,p,['numeric'])||bestMeasure(p);
 let dim=dims[0]||p.cats.find(c=>c!==measure);
 let outcome=p.binaryCols.find(c=>semantic(c)==='outcome')||p.binaryCols[0];
 let relation=/affect|impact|influence|associated|relationship|correlat|factor|driver/.test(nq);
 let highest=/highest|top|best|max|most/.test(nq), lowest=/lowest|bottom|worst|min|least/.test(nq);
 let rate=/repeat|retention|churn|conversion|returned|converted|yes rate/.test(nq);
 return {measure,dim,dims,binary,outcome,relation,highest,lowest,rate,nq};
}
function kpiCards(p,q='',plan=null){
 let m=plan?.measure||bestMeasure(p), cards=[];
 cards.push(['Rows',state.rows.length.toLocaleString()]);
 if(isSkillQuestion(q)){
   const skillCol=findSkillColumn(p);
   if(skillCol){
     const result=skillFrequency(state.rows,skillCol,null);
     cards.push(['Distinct skills',result.overallRows.length.toLocaleString()]);
     cards.push(['Skill mentions',result.overallRows.reduce((sum,x)=>sum+x.count,0).toLocaleString()]);
   }
   return cards.map(([label,value])=>`<div class="kpi"><div class="v">${esc(value)}</div><div class="l">${esc(label)}</div></div>`).join('');
 }
 if(m && p.info[m]){
   cards.push([`Avg ${m}`,fmt(mean(p.info[m].nums))]);
 }
 const id=state.cols.find(c=>p.info[c]?.id);
 if(id) cards.push([`Unique ${id}`,uniq(p.rows.map(r=>r[id])).length.toLocaleString()]);
 else if(plan?.dim){
   cards.push([`Groups in ${plan.dim}`,uniq(p.rows.map(r=>r[plan.dim])).length.toLocaleString()]);
 }
 return cards.slice(0,4).map(([label,value])=>`<div class="kpi"><div class="v">${esc(value)}</div><div class="l">${esc(label)}</div></div>`).join('');
}
function build(q){
 let p=state.profile; p.rows=state.rows;
 let plan=detectPlan(q,p), m=plan.measure||bestMeasure(p), d=plan.dim||p.cats[0];
 $('dashTitle').textContent=q||'Automatic overview';
 $('plan').textContent=`Plan: ${m||'—'} × ${d||'—'}${plan.rate?' · rate analysis':''}`;
 $('kpis').innerHTML=kpiCards(p,q,plan);
 let charts=[], insights=[];
 // Skill-demand questions need token-level counting, not numeric measure × category logic.
 if(isSkillQuestion(q)){
   const skillCol=findSkillColumn(p);
   const categoryCol=Object.keys(p.info).find(c=>/job category|job family|category/.test(norm(c))) || null;
   if(skillCol){
     const result=skillFrequency(state.rows,skillCol,categoryCol);
     const top=result.overallRows.slice(0,12);
     $('plan').textContent=`Plan: count individual skills in ${skillCol}${categoryCol?` × ${categoryCol}`:''}`;
     if(top.length){
       const max=top[0].count;
       charts.push(chartBar('Most frequently required technical skills',top,'count','',true));
       if(categoryCol && result.categoryRows.length){
         charts.push(tableChart('Top skills within each job category',['Job category','Skill','Job postings mentioning skill'],result.categoryRows.slice(0,60)));
       }
       const first=top[0];
       insights.push(`${first.g} is the most frequently listed skill, appearing ${fmt(first.count)} times across ${state.rows.length.toLocaleString()} job postings.`);
       if(top[1]) insights.push(`${top[1].g} is the second most frequently listed skill (${fmt(top[1].count)} postings).`);
       insights.push(`Skills were split into individual values from "${skillCol}" and counted once per posting; repeated mentions within one posting are counted once.`);
       if(categoryCol) insights.push(`The category breakdown covers ${result.categoryCount} job categories.`);
     } else {
       insights.push(`The "${skillCol}" column was found, but no individual skills could be extracted. Check the delimiter format in that column.`);
     }
   } else {
     insights.push('This question requires a skills column (for example, required_skills), but no matching column was detected in the dataset.');
   }
   $('charts').innerHTML=charts.join('');
   $('insights').innerHTML=`<h3>Automatic insights</h3><ul>${insights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
   return;
 }
 // Explicit two-dimension questions: rank combinations once, without redundant single-dimension charts.
 const qNormalized=norm(q);
 const mentionsTitle=mentionsColumn(q,'job_title');
 const mentionsCategory=mentionsColumn(q,'job_category');
 const asksCombination=/combination|combinations|across both|by both/.test(qNormalized) ||
   (mentionsTitle && mentionsCategory && /\band\b/.test(qNormalized));
 if(asksCombination && plan.dims.length>=2 && m){
   const a=plan.dims[0], b=plan.dims[1], buckets=new Map();
   state.rows.forEach(r=>{
     const av=String(r[a]??'').trim(), bv=String(r[b]??'').trim(), v=parseNum(r[m]);
     if(!av||!bv||v===null) return;
     const key=`${av} · ${bv}`;
     if(!buckets.has(key)) buckets.set(key,[]);
     buckets.get(key).push(v);
   });
   const data=[...buckets.entries()].map(([g,values])=>({g,avg:mean(values),n:values.length}))
     .sort((x,y)=>plan.lowest?x.avg-y.avg:y.avg-x.avg).slice(0,10);
   $('plan').textContent=`Plan: average ${m} by ${a} × ${b}`;
   if(data.length){
     charts.push(chartBar(`Highest average ${m} by ${a} × ${b} combination`,data,'avg','',true));
     const best=data[0];
     insights.push(`${best.g} has the ${plan.lowest?'lowest':'highest'} average ${m} (${fmt(best.avg)}) across ${best.n} postings.`);
     insights.push(`Compared ${buckets.size.toLocaleString()} distinct ${a} × ${b} combinations using average ${m}.`);
   } else insights.push('There were not enough valid values to compare the requested combinations.');
   $('charts').innerHTML=charts.join('');
   $('insights').innerHTML=`<h3>Automatic insights</h3><ul>${insights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
   return;
 }
 // Specific factor → binary outcome
 if(plan.relation && (plan.rate||plan.outcome) && d){
   let target=plan.outcome;
   if(target){
    let data=repeatRate(state.rows,d);
    charts.push(chartBar(`Outcome rate by ${d}`,data,'rate',''));
    let top=data[0], low=data[data.length-1];
    if(top)insights.push(`${top.g} has the highest ${target} rate at ${pct(top.rate)}.`);
    if(low&&top&&low.g!==top.g)insights.push(`${low.g} has the lowest rate at ${pct(low.rate)}.`);
   }
 }
 // Explicit binary factor vs numeric measure
 let factor=plan.binary[0]||p.binaryCols[0];
 if(plan.relation && factor && m){
   let data=groupStats(state.rows,factor,m);
   charts.push(chartBar(`Average ${m} by ${factor}`,data,'avg'));
   if(data.length>=2)insights.push(`${data[0].g} has the highest average ${m} (${fmt(data[0].avg)}), versus ${data[data.length-1].g} (${fmt(data[data.length-1].avg)}).`);
 }
 // Normal categorical comparison
 if(d&&m){
   let data=groupStats(state.rows,d,m);
   if(data.length)charts.push(chartBar(`Average ${m} by ${d}`,data,'avg', '', charts.length===0));
   let best=data[0], worst=data[data.length-1];
   if(best)insights.push(`${best.g} has the highest average ${m} (${fmt(best.avg)}).`);
   if(worst&&best&&worst.g!==best.g)insights.push(`${worst.g} has the lowest average ${m} (${fmt(worst.avg)}).`);
   if(data.length>1)insights.push(`The difference between the highest and lowest group averages is ${fmt(best.avg-worst.avg)} ${m} points/units.`);
 }
 // Quality by dimension
 let rating=p.numeric.find(c=>semantic(c)==='quality');
 const asksQuality=/quality|rating|satisfaction|review|customer experience/.test(norm(q));
 if(asksQuality&&rating&&d&&d!==rating){
   let data=groupStats(state.rows,d,rating);
   charts.push(chartBar(`Average ${rating} by ${d}`,data,'avg'));
   if(data[0])insights.push(`${data[0].g} has the highest average ${rating} (${fmt(data[0].avg)}).`);
 }
 // Two-dimensional breakdown when explicitly asked
 if(plan.dims.length>=2&&m){
   let a=plan.dims[0],b=plan.dims[1], map=new Map();
   state.rows.forEach(r=>{let key=`${r[a]} · ${r[b]}`,v=parseNum(r[m]);if(v!==null){if(!map.has(key))map.set(key,[]);map.get(key).push(v)}});
   let data=[...map.entries()].map(([g,x])=>({g,avg:mean(x),n:x.length})).sort((x,y)=>y.avg-x.avg);
   charts.push(chartBar(`Top ${a} × ${b} combinations by ${m}`,data,'avg','',true));
 }
 if(!charts.length){
   let data=p.cats[0]&&m?groupStats(state.rows,p.cats[0],m):[];
   if(data.length)charts.push(chartBar(`Average ${m} by ${p.cats[0]}`,data,'avg','',true));
 }
 let uniqueInsights=uniq(insights).slice(0,5);
 const seenChartTitles=new Set();
 const uniqueCharts=charts.filter(html=>{
   const match=html.match(/<h3>(.*?)<\/h3>/);
   const title=match?match[1]:'';
   if(seenChartTitles.has(title)) return false;
   seenChartTitles.add(title); return true;
 });
 $('charts').innerHTML=uniqueCharts.slice(0,4).join('');
 $('insights').innerHTML=`<h3>Automatic insights</h3><ul>${(uniqueInsights.length?uniqueInsights:['The dashboard was generated from the detected dataset structure.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
}
function loadRows(rows,cols,name='Demo dataset'){
 state.rows=rows;state.cols=cols;state.demo=name.startsWith('Demo');
 state.profile=profileData(rows,cols);
 $('status').textContent=`${name} · ${rows.length.toLocaleString()} rows`;
 renderProfile();renderSuggestions();
 let first=makeSuggestions(state.profile)[0]||'Show an overview of the dataset';
 $('question').value=first;build(first);
}
function parseCSV(text){
  // Remove UTF-8 BOM and normalize line endings.
  text = String(text ?? '').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  if (!text.trim()) return {rows:[], cols:[]};

  // Detect the most likely delimiter from the first non-empty line.
  const firstLine = text.split('\n').find(line => line.trim()) || '';
  const candidates = [',',';','\t','|'];
  const delimiter = candidates
    .map(d => ({d, count:(firstLine.match(new RegExp(d === '|' ? '\\|' : d === '\t' ? '\\t' : d === ';' ? ';' : ',', 'g')) || []).length}))
    .sort((a,b)=>b.count-a.count)[0].d;

  // Character-by-character parser: supports quoted delimiters and escaped quotes.
  const records = [];
  let row = [], cell = '', quoted = false;
  for (let i=0; i<text.length; i++) {
    const ch = text[i], next = text[i+1];
    if (ch === '"') {
      if (quoted && next === '"') { cell += '"'; i++; }
      else quoted = !quoted;
    } else if (ch === delimiter && !quoted) {
      row.push(cell); cell = '';
    } else if (ch === '\n' && !quoted) {
      row.push(cell);
      if (row.some(v => String(v).trim() !== '')) records.push(row);
      row = []; cell = '';
    } else {
      cell += ch;
    }
  }
  row.push(cell);
  if (row.some(v => String(v).trim() !== '')) records.push(row);

  if (records.length < 2) return {rows:[], cols:[]};

  const cols = records[0].map((v,i) => {
    let name = String(v ?? '').trim().replace(/^\uFEFF/, '');
    return name || `Column_${i+1}`;
  });

  // Remove fully empty header columns and normalize row widths.
  const keep = cols.map((c,i)=>({c,i})).filter(({c,i})=>c!=='' || records.slice(1).some(r=>String(r[i]??'').trim()!==''));
  const finalCols = keep.map(x=>x.c);
  const rows = records.slice(1).map(record => {
    const obj = {};
    keep.forEach(({c,i}) => obj[c] = String(record[i] ?? '').trim());
    return obj;
  }).filter(obj => Object.values(obj).some(v=>v!==''));

  return {rows, cols:finalCols};
}
